/* Skin "violet-bloom" (Violet Bloom): the tweakcn preset "violet-bloom" (Apache-2.0, see NOTICE.md), written by packages/skins/tools/tweakcn-skins.ts.
   On when data-skin="violet-bloom" is on <html> (the page) or on any element (a tile of /skins/). Values as tweakcn exports them;
   the spacing scale stays the kit's 0.25rem. Fonts: Plus Jakarta Sans (Google Fonts, loaded when the skin is on). */
[data-skin="violet-bloom"] {
  --background: hsl(0 0% 99%);
  --foreground: hsl(0 0% 0%);
  --card: hsl(0 0% 99%);
  --card-foreground: hsl(0 0% 0%);
  --popover: hsl(0 0% 99%);
  --popover-foreground: hsl(0 0% 0%);
  --primary: hsl(258 100% 60%);
  --primary-foreground: hsl(0 0% 100%);
  --secondary: hsl(214 24% 94%);
  --secondary-foreground: hsl(0 0% 3%);
  --muted: hsl(0 0% 96%);
  --muted-foreground: hsl(0 0% 32%);
  --accent: hsl(213 100% 96%);
  --accent-foreground: hsl(216.3 76% 49%);
  --destructive: hsl(357.3 64.7% 53.3%);
  --destructive-foreground: hsl(0 0% 100%);
  --border: hsl(240 17% 92%);
  --input: hsl(0 0% 92%);
  --ring: hsl(0 0% 0%);
  --chart-1: hsl(148.1 53.4% 53.7%);
  --chart-2: hsl(258 100% 60%);
  --chart-3: hsl(25 98% 58%);
  --chart-4: hsl(217.1 76.7% 54.5%);
  --chart-5: hsl(0 0% 45%);
  --sidebar: hsl(210 43% 97%);
  --sidebar-foreground: hsl(0 0% 0%);
  --sidebar-primary: hsl(0 0% 0%);
  --sidebar-primary-foreground: hsl(0 0% 100%);
  --sidebar-accent: hsl(0 0% 92%);
  --sidebar-accent-foreground: hsl(0 0% 0%);
  --sidebar-border: hsl(0 0% 92%);
  --sidebar-ring: hsl(0 0% 0%);
  --font-sans: Plus Jakarta Sans, sans-serif;
  --font-serif: Lora, serif;
  --font-mono: IBM Plex Mono, monospace;
  --radius: 1.4rem;
  --shadow-2xs: 0px 2px 3px 0px hsl(0 0% 0% / 0.08);
  --shadow-xs: 0px 2px 3px 0px hsl(0 0% 0% / 0.08);
  --shadow-sm: 0px 2px 3px 0px hsl(0 0% 0% / 0.16), 0px 1px 2px -1px hsl(0 0% 0% / 0.16);
  --shadow: 0px 2px 3px 0px hsl(0 0% 0% / 0.16), 0px 1px 2px -1px hsl(0 0% 0% / 0.16);
  --shadow-md: 0px 2px 3px 0px hsl(0 0% 0% / 0.16), 0px 2px 4px -1px hsl(0 0% 0% / 0.16);
  --shadow-lg: 0px 2px 3px 0px hsl(0 0% 0% / 0.16), 0px 4px 6px -1px hsl(0 0% 0% / 0.16);
  --shadow-xl: 0px 2px 3px 0px hsl(0 0% 0% / 0.16), 0px 8px 10px -1px hsl(0 0% 0% / 0.16);
  --shadow-2xl: 0px 2px 3px 0px hsl(0 0% 0% / 0.40);
  --tracking-normal: -0.025em;
  --tracking-tighter: calc(var(--tracking-normal) - 0.05em);
  --tracking-tight: calc(var(--tracking-normal) - 0.025em);
  --tracking-wide: calc(var(--tracking-normal) + 0.025em);
  --tracking-wider: calc(var(--tracking-normal) + 0.05em);
  --tracking-widest: calc(var(--tracking-normal) + 0.1em);
  --destructive-hover: hsl(357.3 64.7% 47.3%);
}

:is(.dark, [data-theme="dark"]) [data-skin="violet-bloom"],
[data-skin="violet-bloom"]:is(.dark, [data-theme="dark"]) {
  --background: hsl(225 7% 11%);
  --foreground: hsl(0 0% 94%);
  --card: hsl(228 7% 14%);
  --card-foreground: hsl(0 0% 94%);
  --popover: hsl(228 7% 14%);
  --popover-foreground: hsl(0 0% 94%);
  --primary: hsl(258.1 89% 64.3%);
  --primary-foreground: hsl(0 0% 100%);
  --secondary: hsl(227 10% 18%);
  --secondary-foreground: hsl(0 0% 94%);
  --muted: hsl(227 10% 18%);
  --muted-foreground: hsl(0 0% 63%);
  --accent: hsl(217.2 32.6% 17.5%);
  --accent-foreground: hsl(208.2 100% 73.7%);
  --destructive: hsl(358.2 55.3% 53.5%);
  --destructive-foreground: hsl(0 0% 100%);
  --border: hsl(223 6% 21%);
  --input: hsl(223 6% 21%);
  --ring: hsl(258 100% 68%);
  --chart-1: hsl(142 69% 58%);
  --chart-2: hsl(258 100% 68%);
  --chart-3: hsl(0 94% 82%);
  --chart-4: hsl(217.5 87.6% 65.3%);
  --chart-5: hsl(0 0% 63%);
  --sidebar: hsl(240 4% 9%);
  --sidebar-foreground: hsl(0 0% 94%);
  --sidebar-primary: hsl(258 100% 68%);
  --sidebar-primary-foreground: hsl(0 0% 100%);
  --sidebar-accent: hsl(227 10% 18%);
  --sidebar-accent-foreground: hsl(258 100% 68%);
  --sidebar-border: hsl(223 6% 21%);
  --sidebar-ring: hsl(258 100% 68%);
  --shadow-2xs: 0px 2px 3px 0px hsl(0 0% 0% / 0.08);
  --shadow-xs: 0px 2px 3px 0px hsl(0 0% 0% / 0.08);
  --shadow-sm: 0px 2px 3px 0px hsl(0 0% 0% / 0.16), 0px 1px 2px -1px hsl(0 0% 0% / 0.16);
  --shadow: 0px 2px 3px 0px hsl(0 0% 0% / 0.16), 0px 1px 2px -1px hsl(0 0% 0% / 0.16);
  --shadow-md: 0px 2px 3px 0px hsl(0 0% 0% / 0.16), 0px 2px 4px -1px hsl(0 0% 0% / 0.16);
  --shadow-lg: 0px 2px 3px 0px hsl(0 0% 0% / 0.16), 0px 4px 6px -1px hsl(0 0% 0% / 0.16);
  --shadow-xl: 0px 2px 3px 0px hsl(0 0% 0% / 0.16), 0px 8px 10px -1px hsl(0 0% 0% / 0.16);
  --shadow-2xl: 0px 2px 3px 0px hsl(0 0% 0% / 0.40);
  --destructive-hover: hsl(358.2 55.3% 47.5%);
}

:root[data-skin="violet-bloom"] body { letter-spacing: var(--tracking-normal); }
[data-skin="violet-bloom"] .shadow-xs { --tw-shadow: var(--shadow-xs); }
[data-skin="violet-bloom"] .shadow-sm { --tw-shadow: var(--shadow-sm); }
[data-skin="violet-bloom"] .shadow { --tw-shadow: var(--shadow); }
[data-skin="violet-bloom"] .shadow-md { --tw-shadow: var(--shadow-md); }
[data-skin="violet-bloom"] .shadow-lg { --tw-shadow: var(--shadow-lg); }
[data-skin="violet-bloom"] .shadow-xl { --tw-shadow: var(--shadow-xl); }
